#!/usr/bin/env node
/**
 * Generate apps/web/src/components/providers/presets.generated.ts from the single
 * source of truth packages/application/src/providers/presets.data.ts.
 *
 *   node node_modules/tsx/dist/cli.mjs scripts/sync-web-presets.mjs --check
 *   node node_modules/tsx/dist/cli.mjs scripts/sync-web-presets.mjs --write
 *
 * --check exits 1 when the generated file is missing or stale.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const source = path.join(root, 'packages/application/src/providers/presets.data.ts');
const target = path.join(root, 'apps/web/src/components/providers/presets.generated.ts');

const HEADER = '// GENERATED by scripts/sync-web-presets.mjs — do not edit; run --write.';

const TYPES = `export type ProviderCategory = 'cn' | 'official' | 'aggregator' | 'local' | 'intl';

export interface PresetInfo {
  id: string;
  name: string;
  protocol: 'openai-compatible' | 'anthropic' | 'mock';
  baseUrl: string;
  defaultModel: string;
  hint?: string;
  category: ProviderCategory;
  auth?: 'api-key' | 'oauth' | 'env' | 'none';
}`;

const order = ['category', 'id', 'name', 'protocol', 'baseUrl', 'defaultModel', 'hint', 'auth'];

function quote(value) {
  return `'${String(value).replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

function renderEntry(preset) {
  const parts = [];
  for (const key of ['id', 'name', 'protocol', 'baseUrl', 'defaultModel']) {
    if (preset[key] === undefined) continue;
    parts.push(`${key}: ${quote(preset[key])}`);
  }
  if (preset.hint !== undefined) parts.push(`hint: ${quote(preset.hint)}`);
  parts.push(`category: ${quote(preset.category)}`);
  if (preset.auth !== undefined) parts.push(`auth: ${quote(preset.auth)}`);
  // keep the historical key order used by the hand-written file
  const ordered = order
    .map(key => parts.find(p => p.startsWith(`${key}: `)))
    .filter(Boolean);
  return `  { ${ordered.join(', ')} },`;
}

async function build() {
  const mod = await import(`file://${source.replace(/\\/g, '/')}`);
  const catalog = mod.PROVIDER_CATALOG;
  if (!Array.isArray(catalog) || catalog.length === 0) {
    throw new Error(`PROVIDER_CATALOG missing or empty in ${source}`);
  }
  const body = catalog.map(renderEntry).join('\n');
  return `${HEADER}\n\n${TYPES}\n\nexport const PROVIDER_PRESETS_CATALOG: PresetInfo[] = [\n${body}\n];\n`;
}

const args = process.argv.slice(2);
const write = args.includes('--write');
const expected = await build();

if (write) {
  fs.writeFileSync(target, expected, 'utf8');
  console.log(`wrote ${path.relative(root, target)} (${expected.split('\n').length} lines)`);
  process.exit(0);
}

if (!fs.existsSync(target)) {
  console.error(`missing ${path.relative(root, target)}; run --write`);
  process.exit(1);
}
const actual = fs.readFileSync(target, 'utf8');
if (actual !== expected) {
  const a = actual.split('\n');
  const b = expected.split('\n');
  const first = a.findIndex((line, i) => line !== b[i]);
  console.error(`stale ${path.relative(root, target)} at line ${first + 1}`);
  console.error(`  expected: ${JSON.stringify(b[first] ?? '<eof>')}`);
  console.error(`  actual:   ${JSON.stringify(a[first] ?? '<eof>')}`);
  process.exit(1);
}
console.log(`ok ${path.relative(root, target)} (${expected.split('\n').length} lines)`);
